<?php require __DIR__.'/app/bootstrap.php';require __DIR__.'/app/notifications.php';$error='';$items=cart_items();$key=$_SESSION['checkout_key']??=bin2hex(random_bytes(32));
if($_SERVER['REQUEST_METHOD']==='POST'){
 check_csrf();$postedKey=(string)($_POST['checkout_key']??'');
 if(!hash_equals($key,$postedKey))$error='Checkout has changed. Refresh and try again.';
 else{
 $name=trim((string)($_POST['name']??''));$phone=preg_replace('/[\s-]/','',(string)($_POST['phone']??''));$email=trim((string)($_POST['email']??''));$address=trim((string)($_POST['address']??''));$area=(string)($_POST['area']??'');$notes=trim((string)($_POST['notes']??''));
 if(strlen($name)<2||strlen($name)>120||!preg_match('/^(?:\+?88)?01[3-9]\d{8}$/',$phone)||strlen($address)<10||strlen($address)>1500||strlen($notes)>1000||strlen($email)>190||($email&&!filter_var($email,FILTER_VALIDATE_EMAIL))||!in_array($area,['dhaka','outside'],true)||empty($_POST['agree']))$error='Please enter a valid name, Bangladesh phone number, delivery address and area, and accept the order terms.';
 else{try{db()->beginTransaction();
   $existing=query('SELECT access_token FROM orders WHERE checkout_key=?',[$key])->fetch();
   if($existing){db()->commit();redirect('order.php?token='.$existing['access_token']);}
   $items=cart_items(true);if(!$items||count($items)!==count($_SESSION['cart']??[]))throw new DomainException('Your bag contains an unavailable item. Return to the bag and update it.');
   foreach($items as $p)if($p['stock']!==null&&$p['qty']>(int)$p['stock'])throw new DomainException($p['name'].' in '.$p['size'].' no longer has that quantity available.');
   $subtotal=cart_subtotal($items);$fee=setting('delivery_'.$area);$fee=$fee===null||$fee===''?null:(int)$fee;$total=$fee===null?null:$subtotal+$fee;
   $token=bin2hex(random_bytes(32));$reference='FL-'.strtoupper(bin2hex(random_bytes(5)));
   query('INSERT INTO orders(reference,access_token,checkout_key,customer_name,phone,email,address,area,notes,subtotal,delivery_fee,total) VALUES(?,?,?,?,?,?,?,?,?,?,?,?)',[$reference,$token,$key,$name,$phone,$email,$address,$area,$notes,$subtotal,$fee,$total]);$orderId=db()->lastInsertId();
   foreach($items as $p){query('INSERT INTO order_items(order_id,product_id,product_name,size,unit_price,quantity,stock_reserved) VALUES(?,?,?,?,?,?,?)',[$orderId,$p['id'],$p['name'],$p['size'],$p['price'],$p['qty'],$p['stock']===null?0:1]);if($p['stock']!==null)query('UPDATE variants SET stock=stock-? WHERE product_id=? AND size=?',[$p['qty'],$p['id'],$p['size']]);}
   notification_enqueue((int)$orderId);db()->commit();notification_try((int)$orderId);$_SESSION['cart']=[];$_SESSION['last_order']=$token;redirect('order.php?token='.$token);
 }catch(DomainException $e){if(db()->inTransaction())db()->rollBack();$error=$e->getMessage();}catch(PDOException $e){if(db()->inTransaction())db()->rollBack();if($e->getCode()==='23000'){$existing=query('SELECT access_token FROM orders WHERE checkout_key=?',[$key])->fetch();if($existing)redirect('order.php?token='.$existing['access_token']);}throw $e;}}
 }
}
if(!$items){if(!empty($_SESSION['last_order']))redirect('order.php?token='.$_SESSION['last_order']);redirect('cart.php');}
$dhaka=setting('delivery_dhaka');$outside=setting('delivery_outside');render_header('Checkout'); ?>
<main class="page"><p class="eyebrow">ONE STEP CLOSER</p><h1>Checkout.</h1><?php if($error):?><p class="notice error" role="alert"><?=h($error)?></p><?php endif ?><form method="post" class="checkout-layout" id="checkout-form"><?=csrf_input()?><input type="hidden" name="checkout_key" value="<?=h($key)?>"><section><h2>Delivery details</h2><div class="form-grid"><label>Full name<input name="name" required maxlength="120" autocomplete="name" value="<?=h($_POST['name']??'')?>"></label><label>Phone number<input name="phone" type="tel" required maxlength="20" autocomplete="tel" placeholder="01XXXXXXXXX" value="<?=h($_POST['phone']??'')?>"></label></div><label>Email (optional)<input name="email" type="email" maxlength="190" autocomplete="email" value="<?=h($_POST['email']??'')?>"></label><label>Delivery address<textarea name="address" required minlength="10" maxlength="1500" autocomplete="street-address" placeholder="House, road, area, district and postcode"><?=h($_POST['address']??'')?></textarea></label><label>Delivery area<select name="area" id="delivery-area" required><option value="">Select area</option><option value="dhaka" data-fee="<?=h($dhaka)?>" <?=($_POST['area']??'')==='dhaka'?'selected':''?>>Inside Dhaka</option><option value="outside" data-fee="<?=h($outside)?>" <?=($_POST['area']??'')==='outside'?'selected':''?>>Outside Dhaka</option></select></label><label>Order notes (optional)<textarea name="notes" maxlength="1000"><?=h($_POST['notes']??'')?></textarea></label><h2 class="spaced">Payment</h2><div class="payment-option"><strong>Cash on delivery</strong><p>Pay when your order arrives. The team will confirm your order before dispatch.</p></div><div class="payment-option disabled"><strong>bKash <span class="badge">COMING SOON</span></strong><p>Online payment is not active yet.</p></div><label class="check-label"><input type="checkbox" name="agree" value="1" required <?=isset($_POST['agree'])?'checked':''?>><span>I agree to the <a href="<?=url('info.php')?>" target="_blank">order and privacy information</a>. If delivery fees are pending, the team must confirm them with me before dispatch.</span></label></section>
<aside class="summary-box"><h2>Your order</h2><?php foreach($items as $p):?><div class="summary-line"><span><?=h($p['name'])?> / <?=h($p['size'])?> × <?=$p['qty']?></span><strong><?=money($p['price']*$p['qty'])?></strong></div><?php endforeach ?><div class="summary-line"><span>Subtotal</span><strong id="checkout-subtotal" data-subtotal="<?=cart_subtotal($items)?>"><?=money(cart_subtotal($items))?></strong></div><div class="summary-line"><span>Delivery</span><strong id="delivery-amount">Select area</strong></div><div class="summary-line total"><span>Total</span><strong id="checkout-total">Pending delivery</strong></div><p id="delivery-note">Delivery fees are confirmed before dispatch if a rate is not yet set.</p><button class="button dark" id="place-order">PLACE ORDER REQUEST ↗</button><p class="hint">No online payment is taken. You’ll receive an order reference on the next screen.</p></aside></form></main><?php render_footer(); ?>
